def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start from cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split path into components
    components = path.split('/')

    # Track symlinks followed to prevent infinite loops
    symlink_count = 0
    max_symlinks = 8

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                # Remove the last component from current path
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            # If current is '/', stay at '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            symlink_count += 1
            if symlink_count > max_symlinks:
                return None

            # Get the symlink target
            target = links[candidate]

            # Resolve the target
            if target.startswith('/'):
                # Absolute symlink target
                current = '/'
                target_components = target.split('/')
            else:
                # Relative symlink target - relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Insert remaining components after the symlink
            components = target_components + components[i:]
            i = 0
        else:
            # Not a symlink, just move to this path
            current = candidate

    # Remove trailing slash, unless it's the root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

